229	async function loadClosure(
230		store: AheDurableStore,
231		references: readonly GenerationRef[]
232	): Promise<readonly Readonly<{ readonly bytes: Uint8Array; readonly ref: GenerationRef }>[] | undefined> {
233		const candidates: Array<Readonly<{ readonly bytes: Uint8Array; readonly ref: GenerationRef }>> = [];
234		for (const ref of references) {
235			const loaded = await store.getBlob(ref.digest);
236			if (!loaded.ok || loaded.value === null) return undefined;
237			candidates.push(Object.freeze({ bytes: Uint8Array.from(loaded.value), ref: Object.freeze({ ...ref }) }));
238		}
239		return Object.freeze(candidates);
240	}
