272			active.head.revision === facts.proposedHead.revision + 1 &&
273			active.adoptedGeneration.baseExpectedHead.kind === "present" &&
274			sameHead(active.adoptedGeneration.baseExpectedHead, facts.proposedHead);
275		if (!pending && !adopted) return undefined;
