290		if (generations === undefined) return undefined;
291		if (pending && !validGenerationLineage(generations, facts)) return undefined;
292		if (adopted) {
293			const current = generations.find(({ generationId }) => generationId === facts.currentHead.generationId);
294			const proposed = generations.find(({ generationId }) => generationId === facts.proposedHead.generationId);
