325		const successorTrustBytes = bytesForRef(closure.proposedCandidates, closeResult.successorTrustRef);
326		const currentTrustBytes = closure.currentCandidates.find((candidate) =>
327			sameRef(candidate.ref, closeResult.currentTrustRef)
