407	async function verifySnapshot(
408		facts: Pick<SealedAdoptionFacts, "snapshotDeclaration" | "snapshotStore">,
409		chain: VerifiedChain
410	): Promise<VerifiedSnapshot | undefined> {
411		let scope: Awaited<ReturnType<SealedAdoptionFacts["snapshotStore"]["openScope"]>> | undefined;
412		let port: ReturnType<NonNullable<typeof scope>["verificationQuarantine"]["open"]> | undefined;
413		try {
414			const decoded = decodeSnapshotManifest({
415				exactCanonicalManifestBytes: facts.snapshotDeclaration.exactCanonicalManifestBytes,
416				expectedManifestDigest: facts.snapshotDeclaration.scope.manifestDigest,
417				profile: PROFILE,
418			});
419			scope = await facts.snapshotStore.openScope(facts.snapshotDeclaration);
420			port = scope.verificationQuarantine.open(new AbortController().signal);
