439					if ((await readChunk(descriptor)) === undefined) return undefined;
440				}
441			} else {
442				const verified = verifySnapshotStreamWithReceipt({
443					exactCanonicalManifestBytes: facts.snapshotDeclaration.exactCanonicalManifestBytes,
444					expectedManifestDigest: facts.snapshotDeclaration.scope.manifestDigest,
445					expectedScope: facts.snapshotDeclaration.scope,
446					profile: PROFILE,
447					quarantine: scope.verificationQuarantine,
448					source: Object.freeze({ read: readChunk }),
449				});
450				await verified.completion;
451				await scope.complete(await verified.receipt);
452			}
453			for (const descriptor of decoded.chunks) {
454				if (chunks[descriptor.index] === undefined && (await readChunk(descriptor)) === undefined) return undefined;
455			}
456			if (chunks.length !== decoded.chunks.length || chunks.some((chunk) => chunk === undefined)) return undefined;
