470				payload.anchor !== manifest.anchor ||
471				payload.anchor !== chain.cut.previousAnchor ||
472				payload.objectId !== chain.cut.objectId ||
473				payload.epoch !== chain.cut.epoch ||
474				payload.archiveIndexRoot !== chain.cut.archiveIndexRoot ||
475				payload.blueprintDigest !== chain.cut.blueprintDigest ||
476				manifest.stateDigest !== chain.cut.stateDigest ||
477				manifest.aclDigest !== chain.cut.aclDigest ||
478				hex(hashDomain("ts-drp/state/v3", encodeCanonical(payload.application))) !== manifest.stateDigest ||
479				hex(hashDomain("ts-drp/latched-acl/v3", encodeCanonical(payload.acl))) !== manifest.aclDigest
480			) {
481				return undefined;
482			}
483			return Object.freeze({ exactCanonicalPayloadBytes: payloadBytes, manifest, payload });
484		} catch {
