199	function validGenerationLineage(generations: readonly GenerationRecord[], facts: SealedAdoptionFacts): boolean {
200		const byId = new Map(generations.map((generation) => [generation.generationId, generation]));
201		if (byId.size !== generations.length) return false;
202		const current = byId.get(facts.currentHead.generationId);
203		const proposed = byId.get(facts.proposedHead.generationId);
204		if (
205			current === undefined ||
206			proposed === undefined ||
207			current.state !== "Superseded" ||
208			proposed.state !== "Adopted" ||
209			proposed.baseExpectedHead.kind !== "present" ||
210			!sameHead(proposed.baseExpectedHead, facts.currentHead) ||
211			!sameClosure(current.closure, facts.currentReferences) ||
212			!sameClosure(proposed.closure, facts.proposedReferences)
213		) {
214			return false;
215		}
216		for (const generation of generations) {
217			if (new Set(generation.closure.map(({ digest }) => digest)).size !== generation.closure.length) return false;
218			if (
219				generation.baseExpectedHead.kind === "present" &&
220				(generation.baseExpectedHead.generationId === generation.generationId ||
221					!byId.has(generation.baseExpectedHead.generationId))
222			) {
223				return false;
224			}
225		}
226		return facts.proposedHead.revision === facts.currentHead.revision + 1;
