242	async function readGenerationLineage(
243		store: AheDurableStore,
244		objectId: StorageObjectId
245	): Promise<readonly GenerationRecord[] | undefined> {
246		const generations: GenerationRecord[] = [];
247		const seenCursors = new Set<GenerationPageCursor>();
248		let cursor: GenerationPageCursor | undefined;
249		for (;;) {
250			const page = await store.readGenerationPage({
251				...(cursor === undefined ? {} : { cursor }),
252				limit: 128,
253				objectId,
254			});
255			if (!page.ok || (page.value.generations.length === 0 && page.value.nextCursor !== null)) return undefined;
256			generations.push(...page.value.generations);
257			if (page.value.nextCursor === null) return Object.freeze(generations);
258			if (seenCursors.has(page.value.nextCursor)) return undefined;
259			seenCursors.add(page.value.nextCursor);
260			cursor = page.value.nextCursor;
261		}
262	}
