264	async function recoverClosure(facts: SealedAdoptionFacts): Promise<RecoveredClosure | undefined> {
265		const recovered = await facts.store.recoverActiveGeneration(facts.objectId);
266		if (!recovered.ok || recovered.value.kind !== "active") return undefined;
267		const active = recovered.value;
268		const pending = sameHead(active.head, facts.proposedHead);
269		const adopted =
270			!pending &&
271			active.head.objectId === facts.proposedHead.objectId &&
272			active.head.revision === facts.proposedHead.revision + 1 &&
273			active.adoptedGeneration.baseExpectedHead.kind === "present" &&
274			sameHead(active.adoptedGeneration.baseExpectedHead, facts.proposedHead);
275		if (!pending && !adopted) return undefined;
276		if (
277			pending &&
278			(active.references.length !== facts.proposedReferences.length ||
279				active.adoptedGeneration.closure.length !== facts.proposedReferences.length ||
280				!facts.proposedReferences.every((ref, index) => sameRef(ref, active.references[index] as GenerationRef)) ||
281				!facts.proposedReferences.every((ref, index) =>
282					sameRef(ref, active.adoptedGeneration.closure[index] as GenerationRef)
283				))
284		) {
285			return undefined;
286		}
287		const closureDigest = digestClosure(active.references);
288		if (!closureDigest.ok || closureDigest.value !== active.head.closureDigest) return undefined;
289		const generations = await readGenerationLineage(facts.store, facts.objectId);
290		if (generations === undefined) return undefined;
291		if (pending && !validGenerationLineage(generations, facts)) return undefined;
292		if (adopted) {
293			const current = generations.find(({ generationId }) => generationId === facts.currentHead.generationId);
294			const proposed = generations.find(({ generationId }) => generationId === facts.proposedHead.generationId);
295			const successor = generations.find(({ generationId }) => generationId === active.head.generationId);
296			if (
297				current?.state !== "Superseded" ||
298				proposed?.state !== "Superseded" ||
299				successor?.state !== "Adopted" ||
300				proposed.baseExpectedHead.kind !== "present" ||
301				!sameHead(proposed.baseExpectedHead, facts.currentHead) ||
302				successor.baseExpectedHead.kind !== "present" ||
303				!sameHead(successor.baseExpectedHead, facts.proposedHead)
304			) {
305				return undefined;
306			}
307		}
308		const [currentCandidates, proposedCandidates] = await Promise.all([
309			loadClosure(facts.store, facts.currentReferences),
310			loadClosure(facts.store, facts.proposedReferences),
311		]);
312		return currentCandidates === undefined || proposedCandidates === undefined
313			? undefined
314			: Object.freeze({ currentCandidates, proposedCandidates });
315	}
