321	function verifyChain(facts: SealedAdoptionFacts, closure: RecoveredClosure): VerifiedChain | undefined {
322		const { closeResult } = facts;
323		const cutBytes = bytesForRef(closure.proposedCandidates, closeResult.cutValueRef);
324		const commitBytes = bytesForRef(closure.proposedCandidates, closeResult.commitQcRef);
325		const successorTrustBytes = bytesForRef(closure.proposedCandidates, closeResult.successorTrustRef);
326		const currentTrustBytes = closure.currentCandidates.find((candidate) =>
327			sameRef(candidate.ref, closeResult.currentTrustRef)
328		)?.bytes;
329		if (
330			cutBytes === undefined ||
331			commitBytes === undefined ||
332			successorTrustBytes === undefined ||
333			currentTrustBytes === undefined
334		) {
335			return undefined;
336		}
337		const opened = openCreatorSuccessorTrust({
338			currentTrust: facts.currentTrust,
339			exactCanonicalCommitQcBytes: commitBytes,
340			exactCanonicalCutValueBytes: cutBytes,
341			exactCanonicalTrustStateRecordBytes: successorTrustBytes,
342		});
343		if (
344			!opened.ok ||
345			opened.trust.currentAnchorDigest !== closeResult.successorAnchorDigest ||
346			opened.trust.currentEpoch !== closeResult.successorEpoch
347		) {
348			return undefined;
349		}
350		const advance = inspectCreatorTrustAdvance({
351			current: { candidates: closure.currentCandidates, closure: facts.currentReferences },
352			proofRefs: [closeResult.cutValueRef, closeResult.commitQcRef],
353			proposed: { candidates: closure.proposedCandidates, closure: facts.proposedReferences },
354		});
355		if (!advance.ok) return undefined;
356		const cut = canonicalRecord(cutBytes);
357		const currentTrustRecord = canonicalRecord(currentTrustBytes);
358		const successorTrustRecord = canonicalRecord(successorTrustBytes);
359		if (
360			cut === undefined ||
361			currentTrustRecord === undefined ||
362			successorTrustRecord === undefined ||
363			!(currentTrustRecord.exactCanonicalCurrentAnchorPreimageBytes instanceof Uint8Array) ||
364			!(successorTrustRecord.exactCanonicalCurrentAnchorPreimageBytes instanceof Uint8Array)
365		) {
366			return undefined;
367		}
368		const currentAnchor = canonicalRecord(currentTrustRecord.exactCanonicalCurrentAnchorPreimageBytes);
369		const successorAnchorBytes = Uint8Array.from(successorTrustRecord.exactCanonicalCurrentAnchorPreimageBytes);
370		const successorAnchor = canonicalRecord(successorAnchorBytes);
371		const projections = closure.currentCandidates
372			.map(({ bytes }) => canonicalRecord(bytes))
373			.filter((candidate) => candidate?.kind === "v3-live-generation-1");
374		const currentProjection = projections.length === 1 ? projections[0] : undefined;
375		if (
376			currentAnchor === undefined ||
377			successorAnchor === undefined ||
378			currentProjection === undefined ||
379			typeof currentProjection.artifactDigest !== "string" ||
380			typeof currentProjection.artifactId !== "string" ||
381			typeof currentProjection.blueprintDigest !== "string" ||
382			typeof currentProjection.catalogDigest !== "string" ||
383			typeof currentProjection.runtimeProfile !== "string" ||
384			currentProjection.blueprintDigest !== currentAnchor.blueprintDigest ||
385			currentProjection.blueprintDigest !== successorAnchor.blueprintDigest
386		) {
387			return undefined;
388		}
389		return Object.freeze({
390			currentAnchor,
391			currentTrustRecord,
392			currentCatalog: Object.freeze({
393				artifactDigest: currentProjection.artifactDigest,
394				artifactId: currentProjection.artifactId,
395				blueprintDigest: currentProjection.blueprintDigest,
396				catalogDigest: currentProjection.catalogDigest,
397				runtimeProfile: currentProjection.runtimeProfile,
398			}),
399			cut,
400			successorAnchor,
401			successorAnchorBytes,
402			successorTrust: opened.trust,
403			successorTrustRecord,
404		});
405	}
