407	async function verifySnapshot(
408		facts: Pick<SealedAdoptionFacts, "snapshotDeclaration" | "snapshotStore">,
409		chain: VerifiedChain
410	): Promise<VerifiedSnapshot | undefined> {
411		let scope: Awaited<ReturnType<SealedAdoptionFacts["snapshotStore"]["openScope"]>> | undefined;
412		let port: ReturnType<NonNullable<typeof scope>["verificationQuarantine"]["open"]> | undefined;
413		try {
414			const decoded = decodeSnapshotManifest({
415				exactCanonicalManifestBytes: facts.snapshotDeclaration.exactCanonicalManifestBytes,
416				expectedManifestDigest: facts.snapshotDeclaration.scope.manifestDigest,
417				profile: PROFILE,
418			});
419			scope = await facts.snapshotStore.openScope(facts.snapshotDeclaration);
420			port = scope.verificationQuarantine.open(new AbortController().signal);
421			const chunks: Uint8Array[] = [];
422			const readChunk = async (descriptor: Readonly<{ readonly index: number }>): Promise<Uint8Array | undefined> => {
423				const selected = decoded.chunks[descriptor.index];
424				if (selected === undefined) return undefined;
425				const bytes = await port?.read(selected);
426				if (
427					bytes === undefined ||
428					bytes.byteLength !== selected.byteLength ||
429					snapshotChunkDigest(selected.index, bytes) !== selected.digest
430				) {
431					return undefined;
432				}
433				chunks[selected.index] = Uint8Array.from(bytes);
434				return bytes;
435			};
436			const status = await scope.status();
437			if (status.kind === "verified") {
438				for (const descriptor of decoded.chunks) {
439					if ((await readChunk(descriptor)) === undefined) return undefined;
440				}
441			} else {
442				const verified = verifySnapshotStreamWithReceipt({
443					exactCanonicalManifestBytes: facts.snapshotDeclaration.exactCanonicalManifestBytes,
444					expectedManifestDigest: facts.snapshotDeclaration.scope.manifestDigest,
445					expectedScope: facts.snapshotDeclaration.scope,
446					profile: PROFILE,
447					quarantine: scope.verificationQuarantine,
448					source: Object.freeze({ read: readChunk }),
449				});
450				await verified.completion;
451				await scope.complete(await verified.receipt);
452			}
453			for (const descriptor of decoded.chunks) {
454				if (chunks[descriptor.index] === undefined && (await readChunk(descriptor)) === undefined) return undefined;
455			}
456			if (chunks.length !== decoded.chunks.length || chunks.some((chunk) => chunk === undefined)) return undefined;
457			const payloadBytes = new Uint8Array(chunks.reduce((total, chunk) => total + chunk.byteLength, 0));
458			let offset = 0;
459			for (const chunk of chunks) {
460				payloadBytes.set(chunk, offset);
461				offset += chunk.byteLength;
462			}
463			const payload = canonicalRecord(payloadBytes);
464			const manifest = canonicalRecord(facts.snapshotDeclaration.exactCanonicalManifestBytes);
465			if (
466				payload === undefined ||
467				manifest === undefined ||
468				facts.snapshotDeclaration.scope.manifestDigest !== chain.cut.snapshotManifestDigest ||
469				hex(hashDomain("ts-drp/snapshot-payload/v3", payloadBytes)) !== manifest.payloadDigest ||
470				payload.anchor !== manifest.anchor ||
471				payload.anchor !== chain.cut.previousAnchor ||
472				payload.objectId !== chain.cut.objectId ||
473				payload.epoch !== chain.cut.epoch ||
474				payload.archiveIndexRoot !== chain.cut.archiveIndexRoot ||
475				payload.blueprintDigest !== chain.cut.blueprintDigest ||
476				manifest.stateDigest !== chain.cut.stateDigest ||
477				manifest.aclDigest !== chain.cut.aclDigest ||
478				hex(hashDomain("ts-drp/state/v3", encodeCanonical(payload.application))) !== manifest.stateDigest ||
479				hex(hashDomain("ts-drp/latched-acl/v3", encodeCanonical(payload.acl))) !== manifest.aclDigest
480			) {
481				return undefined;
482			}
483			return Object.freeze({ exactCanonicalPayloadBytes: payloadBytes, manifest, payload });
484		} catch {
485			return undefined;
486		} finally {
487			try {
488				await port?.discard();
489			} finally {
490				await scope?.release();
491			}
492		}
493	}
