			proposedGeneration.baseExpectedHead.kind !== "present" ||
			candidate.objectId !== objectId ||
			proposedGeneration.objectId !== objectId ||
			currentGeneration.objectId !== objectId ||
			proposedHead.revision !== currentHead.revision + 1
