189	async function activateMaterial(
190		material: CreatorSuccessorLiveMaterial,
191		bindings: CreatorSuccessorRuntimeBindings
192	): Promise<Readonly<Record<string, unknown>>> {
193		const topic = deriveV3StableTopic(material.successor.trust.objectId, material.pinnedGenesisAnchorDigest);
194		const existing = activeOwners.get(topic);
195		if (existing !== undefined) {
196			return sameBindings(existing.bindings, bindings)
197				? success(material, existing.handle)
198				: failure("authority-unavailable", "creator successor already has a conflicting active owner");
199		}
200		const held = await acquireBrowserLock(topic);
201		if (held !== undefined && "ok" in held && held.ok === false) return held;
202		const lock = held as HeldLock | undefined;
203		const activated = await consumeCreatorSuccessorLive(material, bindings);
204		if (!activated.ok) {
205			await lock?.release();
206			return failure(activated.kind, activated.detail);
207		}
208		const rawHandle = activated.handle as Record<string, unknown> & Readonly<{ deactivate(): void | Promise<void> }>;
209		let active = true;
210		const wrapped = Object.freeze({
211			...rawHandle,
212			deactivate: async (): Promise<void> => {
213				if (!active) return;
214				active = false;
215				await Promise.resolve(rawHandle.deactivate());
216				activeOwners.delete(topic);
217				await lock?.release();
218			},
219		});
220		if (!consumeCreatorSuccessorHandleAlias(rawHandle, wrapped)) {
221			try {
