223			} catch {
224				// Continue to release the sole writer lock and return a typed failure.
225			}
226			await lock?.release();
227			return failure("internal-invariant", "creator successor handle identity is unavailable");
228		}
229		activeOwners.set(topic, Object.freeze({ bindings, handle: wrapped }));
230		return success(material, wrapped);
231	}
