257	 * @param input - Exact cold-reopen carriers, stores, and runtime bindings.
258	 * @returns Active successor custody or a typed fail-closed result.
259	 */
260	export async function reopenCreatorSuccessorAdoption(input: unknown): Promise<Readonly<Record<string, unknown>>> {
261		if (
262			input !== null &&
263			typeof input === "object" &&
264			Object.getPrototypeOf(input) === Object.prototype &&
265			!("expectedRoomHead" in input)
266		) {
267			return failure(
268				"D110C_FLOOR_MIGRATION_REQUIRED",
269				"creator successor reopen requires an authenticated room-head floor"
270			);
