272		const captured = capture(input, COLD_KEYS);
273		if (captured === undefined) return failure("malformed-input", "creator successor reopen input is invalid");
274		const expectedRoomHead = captureCreatorExpectedRoomHead(captured.expectedRoomHead);
275		if (expectedRoomHead === undefined) return failure("D110C_FLOOR_INVALID", "creator room-head floor is invalid");
276		if (captured.authenticationProfile !== "creator-only") {
277			return failure("malformed-input", "creator successor authentication profile is invalid");
278		}
279		if (typeof captured.author !== "string" || typeof captured.signRegisteredVertexDigest !== "function") {
280			return failure("malformed-input", "creator successor local author input is invalid");
281		}
282		const bindings = runtimeBindings(captured);
283		if (bindings === undefined) return failure("malformed-input", "creator successor runtime bindings are invalid");
284		const reopened = await consumeCreatorSuccessorReopen(captured as never);
285		if (!reopened.ok) return failure(reopened.kind, reopened.detail);
286		if (!sameCreatorRoomHead(expectedRoomHead, reopened.material.successor.trust)) {
287			return failure("D110C_FLOOR_MISMATCH", "creator successor differs from the authenticated room-head floor");
288		}
